<?php
declare(strict_types=1);
final class AiService {public function analyze(string $provider,string $question,array $snapshot):array{$question=trim(mb_substr($question,0,1200));if(!$question)throw new InvalidArgumentException('Enter a question.');$system='You are a cautious BTC trading education assistant. Analyze only the supplied timestamped Delta snapshot. Never invent prices, indicators or order flow. Explain uncertainty, conditional scenarios, invalidation and risks. No prediction guarantees profit; this app never executes orders. If data is missing or stale, say so.';$input=json_encode(['snapshot'=>$snapshot,'question'=>$question],JSON_UNESCAPED_SLASHES);if($provider==='openai'){if(!CHATGPT_API_KEY)throw new RuntimeException('CHATGPT_API_KEY is not configured in .env.');$r=$this->post('https://api.openai.com/v1/responses',['model'=>CHATGPT_MODEL,'instructions'=>$system,'input'=>$input,'max_output_tokens'=>900],['Authorization: Bearer '.CHATGPT_API_KEY]);$text=$r['output_text']??'';if(!$text)foreach(($r['output']??[]) as $o)foreach(($o['content']??[]) as $c)if(($c['type']??'')==='output_text')$text.=$c['text']??'';if(!$text)throw new RuntimeException('OpenAI returned no readable text.');return ['provider'=>'openai','model'=>CHATGPT_MODEL,'text'=>trim($text),'timestamp'=>time()];}if($provider==='gemini'){if(!GEMINI_API_KEY)throw new RuntimeException('GEMINI_API_KEY is not configured in .env.');$url='https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode((string)GEMINI_MODEL).':generateContent?key='.rawurlencode((string)GEMINI_API_KEY);$r=$this->post($url,['systemInstruction'=>['parts'=>[['text'=>$system]]],'contents'=>[['role'=>'user','parts'=>[['text'=>$input]]]],'generationConfig'=>['temperature'=>0.2,'maxOutputTokens'=>900]],[]);$text='';foreach(($r['candidates'][0]['content']['parts']??[]) as $p)$text.=($p['text']??'')."
";if(!trim($text))throw new RuntimeException('Gemini returned no readable text.');return ['provider'=>'gemini','model'=>GEMINI_MODEL,'text'=>trim($text),'timestamp'=>time()];}throw new InvalidArgumentException('Provider must be openai or gemini.');}private function post(string $url,array $body,array $headers):array{if(!function_exists('curl_init'))throw new RuntimeException('PHP cURL extension required.');$c=curl_init($url);curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>array_merge(['Content-Type: application/json','Accept: application/json','User-Agent: BTC-Intelligence/1.0'],$headers),CURLOPT_POSTFIELDS=>json_encode($body),CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>30,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);$raw=curl_exec($c);$status=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);$err=curl_error($c);curl_close($c);if($raw===false)throw new RuntimeException('AI connection failed: '.$err);$r=json_decode((string)$raw,true);if($status<200||$status>=300)throw new RuntimeException('AI provider error: '.($r['error']['message']??('HTTP '.$status)));if(!is_array($r))throw new RuntimeException('AI returned invalid JSON.');return $r;}}
